import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class Customer extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      customers: [],
      txtKeyword: ''
    };
  }

  componentDidMount() {
    this.apiGetCustomers();
  }

  // Lấy danh sách khách hàng từ Server
  apiGetCustomers = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/customers', config).then((res) => {
      this.setState({ customers: res.data });
    });
  };

  // Thay đổi trạng thái Hoạt động / Khóa tài khoản
  btnToggleStatusClick = (id, currentActive) => {
    const newActive = currentActive === 1 ? 0 : 1;
    const config = { headers: { 'x-access-token': this.context.token } };
    
    axios.put(`/api/admin/customers/status/${id}`, { active: newActive }, config).then((res) => {
      if (res.data) {
        alert(newActive === 1 ? 'Đã mở khóa tài khoản!' : 'Đã khóa tài khoản khách hàng!');
        this.apiGetCustomers();
      }
    });
  };

  render() {
    const { customers, txtKeyword } = this.state;

    // Lọc khách hàng theo từ khóa tìm kiếm
    const filteredCustomers = customers.filter(cust =>
      (cust.name && cust.name.toLowerCase().includes(txtKeyword.toLowerCase())) ||
      (cust.phone && cust.phone.includes(txtKeyword)) ||
      (cust.email && cust.email.toLowerCase().includes(txtKeyword.toLowerCase()))
    );

    const totalCustomers = customers.length;
    const activeCustomers = customers.filter(c => c.active === 1).length;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>QUẢN LÝ KHÁCH HÀNG TẬP TRUNG</h3>

        {/* 1. Các thẻ Thống kê (Summary Cards) */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '25px' }}>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Tổng khách hàng</div>
            <div style={styles.cardValue}>{totalCustomers}</div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Tài khoản hoạt động</div>
            <div style={{ ...styles.cardValue, color: '#2E7D32' }}>{activeCustomers}</div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Tài khoản bị khóa</div>
            <div style={{ ...styles.cardValue, color: '#C62828' }}>{totalCustomers - activeCustomers}</div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Khách thân thiết</div>
            <div style={{ ...styles.cardValue, color: '#C85A32' }}>{activeCustomers}</div>
          </div>
        </div>

        {/* 2. Bảng Danh sách Khách hàng */}
        <div style={{ backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
            <h4 style={{ margin: 0 }}>Danh sách khách hàng đăng ký</h4>
            <input
              type="text"
              placeholder="Tìm theo tên, SĐT, email..."
              style={{ padding: '8px 14px', borderRadius: '20px', border: '1px solid #CCC', width: '250px' }}
              value={txtKeyword}
              onChange={(e) => this.setState({ txtKeyword: e.target.value })}
            />
          </div>

          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ backgroundColor: '#F4EBE1', borderBottom: '2px solid #DDD' }}>
                <th style={{ padding: '10px' }}>Khách hàng</th>
                <th style={{ padding: '10px' }}>Số điện thoại</th>
                <th style={{ padding: '10px' }}>Email</th>
                <th style={{ padding: '10px' }}>Trạng thái</th>
                <th style={{ padding: '10px' }}>Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {filteredCustomers.map((item) => (
                <tr key={item._id} style={{ borderBottom: '1px solid #EEE' }}>
                  <td style={{ padding: '10px', fontWeight: 'bold' }}>
                    <div>{item.name || 'Khách hàng'}</div>
                    <div style={{ fontSize: '12px', color: '#888' }}>@{item.username}</div>
                  </td>
                  <td style={{ padding: '10px' }}>{item.phone || 'N/A'}</td>
                  <td style={{ padding: '10px' }}>{item.email || 'N/A'}</td>
                  <td style={{ padding: '10px' }}>
                    <span style={{
                      padding: '4px 10px', borderRadius: '12px', fontSize: '12px', color: '#FFF',
                      backgroundColor: item.active === 1 ? '#2E7D32' : '#C62828'
                    }}>
                      {item.active === 1 ? 'Hoạt động' : 'Đã khóa'}
                    </span>
                  </td>
                  <td style={{ padding: '10px' }}>
                    <button
                      onClick={() => this.btnToggleStatusClick(item._id, item.active)}
                      style={{
                        backgroundColor: item.active === 1 ? '#D32F2F' : '#2E7D32',
                        color: '#FFF', border: 'none', padding: '5px 12px', borderRadius: '4px', cursor: 'pointer'
                      }}
                    >
                      {item.active === 1 ? 'Khóa tài khoản' : 'Mở khóa'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }
}

const styles = {
  card: {
    backgroundColor: '#FFF',
    padding: '16px',
    borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
    textAlign: 'center'
  },
  cardTitle: {
    fontSize: '13px',
    color: '#666',
    marginBottom: '6px'
  },
  cardValue: {
    fontSize: '22px',
    fontWeight: 'bold',
    color: '#4A2E2B'
  }
};

export default Customer;
